import os,stat,json,subprocess
from pathlib import Path
root=Path("/srv/projects")
old={"final":root/"Engenheira-reversa","trial":root/"REA-Trial"}
f=root/"skill-universal"
services=("ssh","nginx","lowcost-europa","pink-vpn","pm2-iptvpn-bot","pm2-telegram-robot-leads")
aliases=("/home/ubuntu/rea-original-upstream-680","/home/ubuntu/rea-final-runtime","/home/ubuntu/rea-original-upstream-680-evidence","/home/ubuntu/.local/share/rea-chatgpt-trial")
def svc(name):
 try:
  q=subprocess.run(["/usr/bin/systemctl","show",name,"--property=ActiveState,LoadState,FragmentPath","--no-pager"],capture_output=True,text=True,timeout=7)
  return dict(x.split("=",1) for x in q.stdout.strip().splitlines() if "=" in x)
 except Exception as e:return {"error":type(e).__name__}
def size(p):
 try:
  q=subprocess.run(["/usr/bin/du","-sk",str(p)],capture_output=True,text=True,timeout=35)
  return int(q.stdout.split()[0])*1024 if q.returncode==0 else None
 except Exception:return None
res={"mode":"READ_ONLY","old_roots":{},"active_service":{s:svc(s) for s in services},"aliases":{},"project_root_is_physical":root.is_dir() and not root.is_symlink()}
for k,p in old.items():
 try:
  st=p.lstat()
  res["old_roots"][k]={"path":str(p),"exists":True,"physical":stat.S_ISDIR(st.st_mode) and not stat.S_ISLNK(st.st_mode),"device":st.st_dev,"allocated_bytes":size(p),"children":[x.name for x in p.iterdir() if not x.name.startswith(".")][:30]}
 except FileNotFoundError:res["old_roots"][k]={"exists":False}
for name in aliases:
 p=Path(name)
 res["aliases"][name]={"is_symlink":p.is_symlink(),"target":os.readlink(p) if p.is_symlink() else None}
mandatory=[".runtime/npm/rea/node_modules/rea-agents/package.json",".runtime/npm/rea/node_modules/.bin/rea","runtimes/node-22.23.4/bin/node","runtimes/jdk-25.0.5_8/bin/java","tools/rea-providers/ghidra-12.1.4/support/analyzeHeadless","tools/rea-providers/jadx-headless-mcp-0.7.1-all.jar","tools/apktool-3.0.3/bin/apktool"]
res["ferrari"]={"canonical":str(f),"physical":f.is_dir() and not f.is_symlink(),"mandatory":{n:(f/n).is_file() and (f/n).resolve().is_relative_to(f.resolve()) for n in mandatory}}
mounts=[]
for line in Path("/proc/self/mountinfo").read_text().splitlines():
 parts=line.split()
 if len(parts)<5:continue
 m=parts[4].replace("\\040"," ")
 if any(m==str(p) or m.startswith(str(p)+"/") for p in old.values()):mounts.append(m)
res["mountpoints_inside_old_roots"]=mounts
paths=[str(p) for p in old.values()]+list(aliases)
parents=set()
pid=os.getpid()
while pid>1 and pid not in parents:
 parents.add(pid)
 try:
  d=Path("/proc")/str(pid)/"stat"
  s=d.read_text();pid=int(s[s.rfind(")")+2:].split()[1])
 except Exception:break
active=[]
for p in Path("/proc").iterdir():
 if not p.name.isdecimal() or int(p.name) in parents:continue
 try:
  cmd=(p/"cmdline").read_bytes().replace(b"\x00",b" ").decode(errors="replace")
  for path in paths:
   if path in cmd:
    active.append({"pid":int(p.name),"match":path,"kind":"cmdline"});break
  for key in ("cwd","exe","root"):
   try:target=os.readlink(p/key)
   except OSError:continue
   for path in paths:
    if target==path or target.startswith(path+"/"):
     active.append({"pid":int(p.name),"match":path,"kind":key});break
 except OSError:continue
res["active_legacy_process_matches"]=active[:30]
settings=[]
targets=tuple(x.encode() for x in paths)
directories=("/etc/systemd/system","/usr/lib/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin")
count=0
for d in directories:
 if not Path(d).is_dir():continue
 for dp,dirs,files in os.walk(d,followlinks=False):
  dirs[:]=[x for x in dirs if x not in ("archive","backups",".git")]
  for name in files:
   p=Path(dp)/name
   try:
    if p.is_symlink() or not p.is_file() or p.stat().st_size>180000:continue
    count+=1
    b=p.read_bytes()
    for target in targets:
     if target in b:settings.append({"path":str(p),"reference":target.decode()})
   except OSError:pass
res["system_config_references"]={"scanned":count,"matches":settings[:30],"total":len(settings)}
v=os.statvfs(str(root))
res["disk_before"]={"available_bytes":v.f_bavail*v.f_frsize,"total_bytes":v.f_blocks*v.f_frsize}
print(json.dumps(res,ensure_ascii=True,sort_keys=True))
